import csv
from typing import List, Dict, Any, Tuple
from collections import OrderedDict

def parse_csv(raw_csv: str) -> Tuple[List[Dict[str, Any]], List[str]]:
    """
    Parses a raw CSV string into a list of dictionaries (rows) and a list of strings.

    Returns:
        - A tuple containing the parsed rows and the remaining data as strings.
    """
    # Split by delimiter
    lines = raw_csv.split('\n')

    if not lines:
        return [], []

    # Handle multi-line headers
    header_lines = []
    current_header = None

    for line in lines:
        stripped = line.strip()

        if not stripped or stripped.startswith('"'):
            # Quoted line, check if it's a header
            if current_header is None:
                header_lines.append(stripped)
            else:
                # Check if this is the next header
                if stripped == current_header:
                    header_lines.append(stripped)
                else:
                    # Quoted line, check if it's a continuation of the previous header
                    if current_header and not stripped.startswith('"'):
                        header_lines.append(stripped)
                    else:
                        break

        elif stripped == '':
            # Empty line, skip
            continue

        elif stripped.startswith('"') and stripped.endswith('"'):
            # Quoted line, check if it's a header
            if current_header is None:
                header_lines.append(stripped)
            else:
                # Check if this is the next header
                if stripped == current_header:
                    header_lines.append(stripped)
                else:
                    # Quoted line, check if it's a continuation of the previous header
                    if current_header and not stripped.startswith('"'):
                        header_lines.append(stripped)
                    else:
                        break

        elif stripped == '':
            continue

        elif stripped.startswith('['):
            # Multi-line header detected
            header_lines.append(stripped)
            current_header = None
        else:
            # Regular line, check if it's a header
            if current_header is None:
                header_lines.append(stripped)
            else:
                # Check if this is the next header
                if stripped == current_header:
                    header_lines.append(stripped)
                else:
                    # Quoted line, check if it's a continuation of the previous header
                    if current_header and not stripped.startswith('"'):
                        header_lines.append(stripped)
                    else:
                        break

    # Parse headers
    headers = [h.strip() for h in header_lines if h.strip()]

    # Parse rows
    rows = []
    current_row = []

    for line in lines:
        stripped = line.strip()

        if not stripped or stripped.startswith('"'):
            # Quoted line, check if it's a row
            if current_row and current_row[-1] == '"':
                # Check if this is the next row
                if stripped == headers[-1]:
                    current_row.append(stripped)
                else:
                    # Quoted line, check if it's a continuation of the previous row
                    if current_row and not stripped.startswith('"'):
                        current_row.append(stripped)
                    else:
                        break

        elif stripped == '':
            continue

        elif stripped.startswith('['):
            # Multi-line row detected
            current_row.append(stripped)
            current_row = []
        else:
            # Regular line, check if it's a row
            if current_row and current_row[-1] == '"':
                # Check if this is the next row
                if stripped == headers[-1]:
                    current_row.append(stripped)
                else:
                    # Quoted line, check if it's a continuation of the previous row
                    if current_row and not stripped.startswith('"'):
                        current_row.append(stripped)
                    else:
                        break

    return rows, lines

